import re

from ta_moler.cmd.hub.rfswcli.generichub import GenericHub
from moler.exceptions import CommandFailure
from moler.exceptions import ParsingDone


class PoeSwitch(GenericHub):
    """PoeSwitch command class."""

    def __init__(self, connection, port, mode, prompt=None, newline_chars=None, runner=None):
        """
        Turn on/off POE power.

        :param connection: moler connection to device, terminal when command is executed
        :param port: antenna port.
        :param mode: on/off.
        :param prompt: Prompt of the starting shell
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(PoeSwitch, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)

        self.port = port
        self.mode = mode
        self.current_ret["STATUS"] = None

    def build_command_string(self):
        """
        Build command string.

        :return: String representation of command to send over connection to device.
        """
        return f"poe_switch {self.port} {self.mode}"

    def on_new_line(self, line, is_full_line):
        """
        Execute all parsing methods.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._command_error(line)
                self._parse_success_status(line)
                self._parse_line(line)
            except ParsingDone:
                pass
        return super(PoeSwitch, self).on_new_line(line, is_full_line)

    # invalid param!
    _re_invalid = re.compile(r'(?P<CMD_ERROR>invalid.+)', re.I)

    def _command_error(self, line):
        if self._regex_helper.search_compiled(PoeSwitch._re_invalid, line):
            self.set_exception(CommandFailure(self, self._regex_helper.group("CMD_ERROR")))
            raise ParsingDone

    # success
    _re_success = re.compile(r'(?P<STATUS>success)', re.I)

    def _parse_success_status(self, line):
        if self._regex_helper.search_compiled(PoeSwitch._re_success, line):
            self.current_ret["STATUS"] = "success"
            raise ParsingDone

    def _parse_line(self, line):
        self.current_ret["RESULT"] = line
        raise ParsingDone


